SELECT notice_id , notice_title , notice_content , reg_date , readcount , user_type , update_date , status , readcount FROM notice
AND (notice_title LIKE CONCAT ('%', #{searchKeyword}, '%') OR status LIKE CONCAT ('%', #{searchKeyword}, '%') OR user_type LIKE CONCAT ('%', #{searchKeyword}, '%') )
AND notice_title LIKE CONCAT('%', #{searchKeyword}, '%')
AND status = #{searchKeyword}
AND user_type = #{searchKeyword}

mapper.update:
UPDATE notice
SET readcount = readcount + 1
WHERE notice_id = #{noticeId}
